-- 账户流入流出明细表
DROP TABLE IF EXISTS `tb_bank_account_transaction`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `tb_bank_account_transaction` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `account_id` bigint NOT NULL COMMENT '账户ID',
  `transaction_type` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '交易类型(IN-流入/OUT-流出)',
  `amount` decimal(18,2) NOT NULL COMMENT '交易金额',
  `transaction_date` date NOT NULL COMMENT '交易日期',
  `summary` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '交易摘要',
  `business_type` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '业务类型(收款/付款/转账/利息收入/手续费等)',
  `counterparty_account` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '对方账户',
  `counterparty_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '对方名称',
  `balance_after` decimal(18,2) DEFAULT NULL COMMENT '交易后余额',
  `attachment_id` bigint DEFAULT NULL COMMENT '附件ID',
  `related_business_id` bigint DEFAULT NULL COMMENT '关联业务单据ID',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '备注',
  `case_id` bigint DEFAULT NULL COMMENT '案件ID',
  `create_time` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `create_user_id` bigint DEFAULT NULL COMMENT '创建用户ID',
  `update_user_id` bigint DEFAULT NULL COMMENT '更新用户ID',
  `is_deleted` tinyint(1) DEFAULT '0' COMMENT '是否删除: 0-否, 1-是',
  `status` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT 'ACTIVE' COMMENT '状态: ACTIVE-激活, INACTIVE-停用, DELETED-删除',
  PRIMARY KEY (`id`),
  KEY `idx_account_id` (`account_id`),
  KEY `idx_transaction_type` (`transaction_type`),
  KEY `idx_transaction_date` (`transaction_date`),
  KEY `idx_business_type` (`business_type`),
  KEY `idx_case_id` (`case_id`),
  KEY `idx_create_time` (`create_time`),
  KEY `idx_status` (`status`),
  CONSTRAINT `fk_bank_account_transaction_account` FOREIGN KEY (`account_id`) REFERENCES `tb_bank_account` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=1 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin COMMENT='账户流入流出明细表';
/*!40101 SET character_set_client = @saved_cs_client */;

